import numpy as np
from .L01_base import PIVDataProcessorBase as pBase
from .A01_toolbox import float_precsion
import os, inspect, shutil, sys
from dataclasses import dataclass, asdict, fields
import json
from abc import ABC, abstractmethod

class PIVDataProcessorExtensionTemplate(pBase):
    def __init__(self, casename:str):
        super().__init__()
        pBase.load_case(casename=casename)
        self.casename = pBase.CaseInfo.CaseName
        self.result_path  = self.__getpath() + '/' + self.casename
    
    @classmethod
    def __getpath(cls) -> str:
        module = inspect.getmodule(cls)
        current_file_path = os.path.abspath(module.__file__)
        c_file_path, c_file_name = os.path.split(current_file_path)

        cwd = os.path.abspath(pBase.Paths.Working_path)
        plot_folder = pBase.Paths.Plot_foldername.lstrip("/\\")  
        c_relative_path = os.path.relpath(c_file_path, start=cwd)
        path = os.path.join(cwd, plot_folder, c_relative_path, c_file_name[:-3])
        path = os.path.normpath(path) 
        return path
    
    def report(self, str:str):
        self.pBasereport(str, self.result_path + '/log.txt')
    
    @classmethod
    def clean_result_folder(cls, casename: str = None):
        module = inspect.getmodule(cls)
        current_file_path = os.path.abspath(module.__file__)
        c_file_path, c_file_name = os.path.split(current_file_path)

        cwd = os.path.abspath(pBase.Paths.Working_path)
        plot_folder = pBase.Paths.Plot_foldername.lstrip("/\\")  
        c_relative_path = os.path.relpath(c_file_path, start=cwd)
        path = os.path.join(cwd, plot_folder, c_relative_path, c_file_name[:-3])
        path = os.path.normpath(path) 
        print(f'Cleaning and creating directory: {path}')
        if casename is not None:
            path = os.path.join(path, casename)
            path = os.path.normpath(path)

        cls.rm_and_create_directory(path, ifcreate=False)

class GeneralTemplate():
    def __init__(self, folder_name = 'unnamed'):
        if folder_name == '':
            self.result_path = self.__getpath()
        self.result_path = self.__getpath() + '/' + folder_name
        self.make_sure_directory(self.result_path)

    def __getpath(self) -> str:
        frame = inspect.stack()[2]
        module = inspect.getmodule(frame[0])
        current_file_path = os.path.abspath(module.__file__)
        c_file_path, c_file_name = os.path.split(current_file_path) 
        cwd = pBase.Paths.Working_path
        c_relative_path = os.path.relpath(c_file_path, start=cwd)
        plot_path = cwd + pBase.Paths.Plot_foldername + '/' + c_relative_path + '/' + c_file_name[:-3]
        return plot_path 

    @staticmethod    
    def rm_and_create_directory(path_to_directory:str) -> None:
        if os.path.exists(path_to_directory):
            shutil.rmtree(path_to_directory)
        os.makedirs(path_to_directory)

    @staticmethod
    def empty_directory(path_to_directory:str, keep = ()):
        '''
        Delete all subdirectories under `path_to_directory` except those specified in `keep`.'''
        keep = set(keep)
        for name in os.listdir(path_to_directory):
            path = os.path.join(path_to_directory, name)
            if os.path.isdir(path) and name not in keep:
                shutil.rmtree(path)  

    @staticmethod
    def make_sure_directory(path_to_directory:str) -> None:
        if os.path.exists(path_to_directory):
            return
        else:
            os.makedirs(path_to_directory) 
 
    def GTreport(self, str:str = '', logfile:str = '', ifinit = False) -> None:
        '''
            Custom print().

            No need to pay extra attention.
        '''
        if logfile == '':
            logfile = self.result_path+'/log.txt'
        else:
            logfile = self.result_path + logfile
        if ifinit == True:
            with open(logfile,'w') as f:
                sys.stdout = f
                print(str)
        else:
            with open(logfile,'a') as f:
                sys.stdout = f
                print(str)            
        sys.stdout = sys.__stdout__

    @staticmethod
    def save_nparray_to_bin(quantity:np.ndarray, datapath:str):
        with open(datapath, 'wb') as f:
            quantity.tofile(f)  

    @staticmethod
    def load_nparray_from_bin(quantity: np.ndarray, datapath:str, dtype=float_precsion) -> np.ndarray:
        shape = quantity.shape
        quantity = np.fromfile(datapath, dtype = dtype).reshape(shape)
        return quantity
    

    
class LinkedListNodeBase(ABC):
    '''Example:
    class MyNode(LinkedListNodeBase):
        def __init__(self, value: np.ndarray, tag=None, next_node=None):
            super().__init__(next_node)
            self.value = value  
            self.tag = tag     

        def property_to_dict(self):
            return {
                'value': self.value.tolist(), 
                'tag': self.tag
            }

        @classmethod
        def property_from_dict(cls, d):
            value = np.array(d['value'])
            return cls(value=value, tag=d.get('tag'))

    if __name__ == "__main__":
        n2 = MyNode(np.array([3, 4]), tag='b')
        n1 = MyNode(np.array([1, 2]), tag='a', next_node=n2)
        n1.save('linked_array.json')

        head = MyNode.load('linked_array.json')
        current = head
        while current:
            print(f'value: {current.value}, tag: {current.tag}, type: {type(current.value)}')
            current = current.next
    '''
    def __init__(self, next_node=None):
        self.next = next_node

    def link_into_list(self):
        result = []
        current = self
        while current:
            result.append(current.property_to_dict())
            current = current.next
        return result

    @classmethod
    def node_from_list(cls, data_list):
        head = None
        for item in reversed(data_list):
            node = cls.property_from_dict(item)
            node.next = head
            head = node
        return head

    def save(self, filename):
        with open(filename+'.json', 'w', encoding='utf-8') as f:
            json.dump(self.link_into_list(), f, indent=2)

    @classmethod
    def load(cls, filename):
        with open(filename+'.json', 'r', encoding='utf-8') as f:
            data = json.load(f)
        return cls.node_from_list(data)

    @abstractmethod
    def property_to_dict(self):
        pass

    @classmethod
    @abstractmethod
    def property_from_dict(cls, d):
        pass
    
    @staticmethod
    def __getResultPath(ifcleanfolder = False) -> str:
        frame = inspect.stack()[2]
        module = inspect.getmodule(frame[0])
        current_file_path = os.path.abspath(module.__file__)
        c_file_path, c_file_name = os.path.split(current_file_path) 
        cwd = pBase.Paths.Working_path
        c_relative_path = os.path.relpath(c_file_path, start=cwd)
        plot_path = cwd + pBase.Paths.Plot_foldername + '/' + c_relative_path + '/' + c_file_name[:-3]
        if ifcleanfolder == True:
            pBase.rm_and_create_directory(plot_path)
        return plot_path

    @classmethod
    def getResultPath(cls, ifcleanfolder = False) -> str:
        return cls.__getResultPath(ifcleanfolder=ifcleanfolder)

class UncertaintyEstimationTemplate(ABC):
    '''
        An abstract base class for estimating uncertainty in PIV data.
        Usage:

        class S22error(UET):
        def __init__(self, case_name):
            super().__init__(case_name)
        def load_target(self, casename: str):
            fs = FittedSlope(casename)
            fs.load_fitted()
            return fs.fit_avg_dUdX[1][1] * 1000 
            
    '''
    def __init__(self, casename: str):
        self.casename = casename
    
    @abstractmethod
    def load_target(self, casename: str) -> np.ndarray:
        pass

    def estimate_uncertainty(self, filter_range: int = 8, suffix1: str = '_sub1', suffix2: str = '_sub2') -> np.ndarray:
        from .A01_toolbox import nanmean_filter2d
        sub1 = self.load_target(self.casename + suffix1)
        sub2 = self.load_target(self.casename + suffix2)
        diff_sq = (sub1 - sub2) ** 2
        return np.sqrt(nanmean_filter2d(diff_sq, filter_range))

class ParamTable:
    def __init__(self, filename="params.json"):
        self.filename = filename
        self.data = {}
        self.load()

    def load(self):
        if os.path.exists(self.filename):
            with open(self.filename, "r", encoding="utf-8") as f:
                self.data = json.load(f)
        else:
            self.data = {}
 
    def save(self):
        with open(self.filename, "w", encoding="utf-8") as f:
            json.dump(self.data, f, indent=2, ensure_ascii=False)

    def set(self, uid, **params):
        '''
        example:
        params.set("case01", beta=0.99)
        '''
        if uid not in self.data:
            self.data[uid] = {}

        self.data[uid].update(params)
        self.save()

    def get(self, uid):
        '''
        example:
        p = params.get("case001")
        print(p["Lf"], p["coef"])
        '''
        return self.data.get(uid, None)

    def delete(self, uid):
        if uid in self.data:
            del self.data[uid]
            self.save()

    def ids(self):
        return list(self.data.keys())